/** Vocabulary for the explicitly qualified subset of v29 Power benefits. */
export type V29VaultDamageNode = 'Damage' | 'Ultimate Damage' | 'Spotlight Bonus'
export type V29VaultDamagePolicy = 'community-v29-linear-five-percent'
export interface V29VaultDamageBonus {
  node: V29VaultDamageNode
  level: number
  fraction: number
  multiplier: number
  confidence: 'direct-community' | 'corroborated-community'
  nativeParity: false
  sourceUrls: readonly string[]
}
export type V29VaultFreeUpgradeNode = 'Free Attack Upgrade' | 'Free Defense Upgrade' | 'Free Utility Upgrade'
export type V29VaultFreeUpgradePolicy = 'community-v29-relative-free-upgrades'
export interface V29VaultFreeUpgradeBonus {
  node: V29VaultFreeUpgradeNode
  level: number
  fraction: number
  multiplier: number
  confidence: 'direct-player-measurement'
  nativeParity: false
  sourceUrls: readonly string[]
}

/** The three v29 vault trees, as the row keys spell them. */
export type VaultV29TreeKey = 'harmony' | 'power' | 'enemy'

/** One priced row of a v29 tree: an upgrade's key ladder, under the key that names it. */
export interface VaultV29KeyRow {
  /** Row key, `v29:<tree>:<category>:<name>`. */
  readonly key: string
  readonly tree: VaultV29TreeKey
  readonly category: string
  /** The upgrade's name; `<enemy>:<stat>` for an Enemy row. */
  readonly name: string
  /** Keys for each level, in order. */
  readonly levelCosts: readonly number[]
}
